#define RESIDUAL_HIER_VO_NO_MAIN
#include "residual_hier_vo.cpp"
#undef RESIDUAL_HIER_VO_NO_MAIN

// Authenticated approximate fine routing.  Each coarse group owns a directed
// kNN graph over its PQ-decoded residual codes.  The verifier receives the
// authenticated records discovered by a deterministic global best-first walk
// over all selected groups and replays the same visit budget and top-p rule.

struct PGGroup {std::vector<int>ids;std::vector<std::vector<uint16_t>>neighbors;uint16_t entry=0;};

static std::vector<PGGroup> pg_build(const std::vector<std::vector<int>>&groups,const Matrix&decoded,int degree){
    std::vector<PGGroup>out(groups.size());for(size_t g=0;g<groups.size();++g){auto&x=out[g];x.ids=groups[g];int n=x.ids.size();x.neighbors.resize(n);double best=std::numeric_limits<double>::infinity();
        for(int i=0;i<n;++i){double norm=0;for(int j=0;j<decoded.d;++j)norm+=(double)decoded[x.ids[i]][j]*decoded[x.ids[i]][j];if(norm<best){best=norm;x.entry=i;}
            std::vector<std::pair<float,int>>near;near.reserve(n-1);for(int z=0;z<n;++z)if(z!=i)near.push_back({l2(decoded[x.ids[i]],decoded[x.ids[z]],decoded.d),z});int take=std::min<int>(degree,near.size());
            std::partial_sort(near.begin(),near.begin()+take,near.end(),[](const auto&a,const auto&b){return a.first==b.first?a.second<b.second:a.first<b.first;});for(int z=0;z<take;++z)x.neighbors[i].push_back(near[z].second);}}
    return out;
}

struct PGOpen {int group=0;std::vector<int>positions;};
struct PGRun {std::vector<VLState>state;std::vector<std::vector<int>>coarse;std::vector<std::vector<PGOpen>>opened;double recall=0,query_ms=0,records=0,expanded=0,residual_bytes=0,adjacency_bytes=0;};
struct PGItem {float distance=0;int group=0,position=0,id=0;};
struct PGGreater {bool operator()(const PGItem&a,const PGItem&b)const{return a.distance==b.distance?(a.id>b.id):a.distance>b.distance;}};

static PGRun pg_query(const Matrix&xb,const Matrix&q,const std::vector<std::vector<int>>&lists,const std::vector<std::vector<int>>&groups,
        const Matrix&coarse_centers,const Matrix&residual,const CRCodec&coarse_codec,const CRCodec&residual_codec,const std::vector<PGGroup>&graph,
        int coarse_probe,int fine_probe,int k,int degree,int budget,const std::vector<std::vector<int>>&gt){
    PGRun out;out.state.resize(q.rows());out.coarse.resize(q.rows());out.opened.resize(q.rows());uint64_t hits=0;double elapsed=0;
    for(size_t qi=0;qi<q.rows();++qi){auto begin=std::chrono::steady_clock::now();auto clut=coarse_codec.prepare(q[qi]);std::vector<int>corder(groups.size());std::iota(corder.begin(),corder.end(),0);
        std::partial_sort(corder.begin(),corder.begin()+coarse_probe,corder.end(),[&](int a,int b){float x=coarse_codec.distance(q[qi],clut,coarse_centers,a,false),y=coarse_codec.distance(q[qi],clut,coarse_centers,b,false);return x==y?a<b:x<y;});out.coarse[qi].assign(corder.begin(),corder.begin()+coarse_probe);
        std::vector<std::vector<float>>luts(groups.size());std::vector<std::vector<uint8_t>>seen(groups.size()),done(groups.size());std::vector<std::vector<int>>opened(groups.size());std::priority_queue<PGItem,std::vector<PGItem>,PGGreater>frontier;std::vector<std::pair<float,int>>candidate;uint64_t code_bits=0;int records=0,expanded=0;
        auto discover=[&](int g,int p){if(seen[g][p])return;seen[g][p]=1;int id=graph[g].ids[p];float d=residual_codec.distance(nullptr,luts[g],residual,id,false);frontier.push({d,g,p,id});candidate.push_back({d,id});opened[g].push_back(p);++records;std::vector<int>one{id};code_bits+=residual_codec.huffman_bit_count(one);int id_bytes=groups[g].size()<=256?1:2;out.adjacency_bytes+=1.0+id_bytes*std::min<int>(degree,graph[g].neighbors[p].size());};
        for(int z=0;z<coarse_probe;++z){int g=corder[z];auto dc=coarse_codec.decode(coarse_centers,g);std::vector<float>qr(q.d);for(int j=0;j<q.d;++j)qr[j]=q[qi][j]-dc[j];luts[g]=residual_codec.prepare(qr.data());seen[g].assign(groups[g].size(),0);done[g].assign(groups[g].size(),0);discover(g,graph[g].entry);}
        while(records<budget&&!frontier.empty()){auto x=frontier.top();frontier.pop();if(done[x.group][x.position])continue;done[x.group][x.position]=1;++expanded;int take=std::min<int>(degree,graph[x.group].neighbors[x.position].size());for(int z=0;z<take;++z)discover(x.group,graph[x.group].neighbors[x.position][z]);}
        if((int)candidate.size()<fine_probe)throw std::runtime_error("PQ graph budget smaller than fine probe");std::partial_sort(candidate.begin(),candidate.begin()+fine_probe,candidate.end(),[](const auto&a,const auto&b){return a.first==b.first?a.second<b.second:a.first<b.first;});auto&s=out.state[qi];for(int z=0;z<fine_probe;++z)s.lists.push_back(candidate[z].second);
        std::priority_queue<std::pair<float,int>>objects;for(int c:s.lists)for(int id:lists[c]){float d=l2(q[qi],xb[id],xb.d);if((int)objects.size()<k)objects.push({d,id});else if(d<objects.top().first||(d==objects.top().first&&id<objects.top().second)){objects.pop();objects.push({d,id});}}
        if((int)objects.size()!=k)throw std::runtime_error("PQ graph found too few objects");s.tau2=objects.top().first;while(!objects.empty()){s.answer.push_back(objects.top().second);objects.pop();}elapsed+=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count();
        std::unordered_set<int>answer(s.answer.begin(),s.answer.end());for(int id:gt[qi])hits+=answer.count(id);out.records+=records;out.expanded+=expanded;out.residual_bytes+=(code_bits+7)/8.0;for(int g:out.coarse[qi])if(!opened[g].empty())out.opened[qi].push_back({g,std::move(opened[g])});}
    double nq=q.rows();out.recall=hits/(nq*k);out.query_ms=elapsed/nq;out.records/=nq;out.expanded/=nq;out.residual_bytes/=nq;out.adjacency_bytes/=nq;return out;
}

struct PGRoute {double parameters=0,models=0,coarse_codes=0,residual_codes=0,adjacency=0,group_metadata=0,fine_metadata=0,coarse_proofs=0,graph_proofs=0,fine_proofs=0,total=0;};

static PGRoute pg_route(const PGRun&query,const std::vector<std::vector<int>>&groups,const std::vector<int>&group_of,const std::vector<int>&position,
        const RHLayout&layout,const CRCodec&coarse_codec,const CRCodec&residual_codec){
    PGRoute out;out.parameters=96.0+coarse_codec.parameter_bytes()+residual_codec.parameter_bytes()+8.0;out.models=coarse_codec.huffman_model_bytes()+residual_codec.huffman_model_bytes();std::vector<int>all_coarse(groups.size());std::iota(all_coarse.begin(),all_coarse.end(),0);out.coarse_codes=coarse_codec.huffman_bytes(all_coarse);out.residual_codes=query.residual_bytes;out.adjacency=query.adjacency_bytes;
    std::vector<std::vector<int>>selected(groups.size());std::vector<int>mapped;for(size_t qi=0;qi<query.state.size();++qi){const auto&cg=query.coarse[qi];out.group_metadata+=cg.size()*70.0;mapped.clear();for(int g:cg)mapped.push_back(layout.coarse_position[g]);out.coarse_proofs+=hv_dummy_proof_count(groups.size(),mapped)*32.0;
        for(const auto&open:query.opened[qi])out.graph_proofs+=hv_dummy_proof_count(groups[open.group].size(),open.positions)*32.0;for(auto&v:selected)v.clear();for(int leaf:query.state[qi].lists)selected[group_of[leaf]].push_back(position[leaf]);
        for(int g:cg)if(!selected[g].empty()){out.fine_metadata+=selected[g].size()*4.0;out.fine_proofs+=hv_dummy_proof_count(groups[g].size(),selected[g])*32.0;}}
    double nq=query.state.size();out.group_metadata/=nq;out.fine_metadata/=nq;out.coarse_proofs/=nq;out.graph_proofs/=nq;out.fine_proofs/=nq;out.total=out.parameters+out.models+out.coarse_codes+out.residual_codes+out.adjacency+out.group_metadata+out.fine_metadata+out.coarse_proofs+out.graph_proofs+out.fine_proofs+16.0;return out;
}

int main(int argc,char**argv)try{
    auto cfg=cr_args(argc,argv);if(!cfg.coarse_nlist||cfg.coarse_codec.empty()||cfg.residual_codec.empty())throw std::runtime_error("require coarse options plus both codecs");std::cerr<<"Loading/training index...\n";Matrix xb=fvecs(cfg.data+"/sift_base.fvecs",cfg.base),trainq=fvecs(cfg.data+"/sift_learn.fvecs",cfg.train_queries),testq=fvecs(cfg.data+"/sift_query.fvecs",cfg.test_queries);auto lists=hkmeans(xb,cfg.nlist,cfg.iters);auto fine_vector=centers(xb,lists);Matrix fine_centers=cr_matrix(fine_vector);auto groups=hkmeans(fine_centers,cfg.coarse_nlist,cfg.iters);Matrix coarse_centers=cr_matrix(centers(fine_centers,groups));
    std::vector<int>group_of(cfg.nlist,-1),position(cfg.nlist,-1);for(size_t g=0;g<groups.size();++g)for(size_t p=0;p<groups[g].size();++p){group_of[groups[g][p]]=g;position[groups[g][p]]=p;}Matrix residual;residual.d=xb.d;residual.x.resize((size_t)cfg.nlist*xb.d);for(int leaf=0;leaf<cfg.nlist;++leaf)for(int j=0;j<xb.d;++j)residual.x[(size_t)leaf*xb.d+j]=fine_centers[leaf][j]-coarse_centers[group_of[leaf]][j];Matrix empty;CRCodec coarse_codec(cfg.coarse_codec,coarse_centers,empty,std::min(cfg.pq_train,cfg.coarse_nlist),cfg.pq_iters,cfg.seed),residual_codec(cfg.residual_codec,residual,empty,cfg.pq_train,cfg.pq_iters,cfg.seed+1);auto gt=exact_gt(xb,testq,cfg.k);
    auto train=rh_states(xb,trainq,lists,fine_centers,groups,group_of,coarse_centers,residual,coarse_codec,residual_codec,cfg.coarse_nprobe,cfg.nprobe,cfg.k,nullptr),test=rh_states(xb,testq,lists,fine_centers,groups,group_of,coarse_centers,residual,coarse_codec,residual_codec,cfg.coarse_nprobe,cfg.nprobe,cfg.k,&gt);auto boundaries=verification_tree_bounds(xb,trainq,lists,train.state,0,cfg.train_queries);NestedRule quantizer(xb,std::move(boundaries));if(!quantizer.contains(xb))throw std::runtime_error("quantizer containment failure");auto tail=hv_lossless_tail(xb,quantizer);HVLayout identity;identity.routing_position.resize(lists.size());std::iota(identity.routing_position.begin(),identity.routing_position.end(),0);
    int split=cfg.train_queries/2;auto order=hv_downgrade_order(xb,trainq,train.state,0,split,lists,quantizer);std::vector<int>counts{0,8,16,24,32,48,64,80,96,112,128};HVProtocol independent;independent.lossless_tail=true;independent.positional_ids=true;independent.public_dummy=true;int best_count=0;double best=std::numeric_limits<double>::infinity();for(int count:counts){auto b=hv_downgrade_bits(xb.d,order,count);auto e=hv_protocol_evaluate(xb,trainq,train.state,split,cfg.train_queries,lists,quantizer,b,identity,tail,independent,1,false);if(e.total-e.routing<best){best=e.total-e.routing;best_count=count;}}
    auto full_order=hv_downgrade_order(xb,trainq,train.state,0,cfg.train_queries,lists,quantizer);auto bits=hv_downgrade_bits(xb.d,full_order,best_count);auto ie=hv_protocol_evaluate(xb,trainq,train.state,0,cfg.train_queries,lists,quantizer,bits,identity,tail,independent,1,false);HVProtocol fused=independent;fused.fused_commitment=true;auto fe=hv_protocol_evaluate(xb,trainq,train.state,0,cfg.train_queries,lists,quantizer,bits,identity,tail,fused,1,false);const auto&protocol=(fe.total-fe.routing)<(ie.total-ie.routing)?fused:independent;auto baseline_leaf_eval=hv_protocol_evaluate(xb,testq,test.state,0,cfg.test_queries,lists,quantizer,bits,identity,tail,protocol,cfg.repeats,true);double baseline_leaf=baseline_leaf_eval.total-baseline_leaf_eval.routing,leaf_parameters=cr_leaf_parameter_bytes(quantizer,bits);auto layout=rh_learn_layout(train,groups,group_of,position,cfg.seed);auto baseline_route=rh_route(test,groups,group_of,layout,coarse_codec,residual_codec);baseline_route.huffman_total+=leaf_parameters;double baseline_total=baseline_route.huffman_total+baseline_leaf;
    Matrix decoded;decoded.d=residual.d;decoded.x.resize(residual.x.size());for(size_t id=0;id<residual.rows();++id){auto v=residual_codec.decode(residual,id);std::copy(v.begin(),v.end(),decoded.x.begin()+id*(size_t)decoded.d);}std::vector<int>degrees=cfg.max_block==1?std::vector<int>{4,8,12,16}:std::vector<int>{cfg.max_block},budgets=cfg.beam==0?std::vector<int>{3000,5000,7000,8000,9000,10000,11000}:std::vector<int>{cfg.beam};int max_degree=*std::max_element(degrees.begin(),degrees.end());std::cerr<<"Building PQ graph degree="<<max_degree<<"...\n";auto graph=pg_build(groups,decoded,max_degree);
    std::ofstream out(cfg.output);if(!out)throw std::runtime_error("cannot open output");out<<std::setprecision(12)<<"degree,visit_budget,recall,avg_records,avg_expanded,routing_parameters,huffman_models,huffman_coarse_codes,huffman_residual_codes,adjacency_payload,group_metadata,fine_metadata,coarse_proofs,graph_proofs,fine_proofs,routing_total,leaf_total,total_vo,baseline_huffman_total,vo_reduction_vs_baseline,ann_query_ms,baseline_query_ms,violations\n";
    for(int degree:degrees)for(int budget:budgets){std::cerr<<"Query degree="<<degree<<" budget="<<budget<<"...\n";auto run=pg_query(xb,testq,lists,groups,coarse_centers,residual,coarse_codec,residual_codec,graph,cfg.coarse_nprobe,cfg.nprobe,cfg.k,degree,budget,gt);auto route=pg_route(run,groups,group_of,position,layout,coarse_codec,residual_codec);route.parameters+=leaf_parameters;route.total+=leaf_parameters;auto le=hv_protocol_evaluate(xb,testq,run.state,0,cfg.test_queries,lists,quantizer,bits,identity,tail,protocol,cfg.repeats,true);double leaf_total=le.total-le.routing,total=route.total+leaf_total;uint64_t violations=le.object_violations;
        out<<degree<<','<<budget<<','<<run.recall<<','<<run.records<<','<<run.expanded<<','<<route.parameters<<','<<route.models<<','<<route.coarse_codes<<','<<route.residual_codes<<','<<route.adjacency<<','<<route.group_metadata<<','<<route.fine_metadata<<','<<route.coarse_proofs<<','<<route.graph_proofs<<','<<route.fine_proofs<<','<<route.total<<','<<leaf_total<<','<<total<<','<<baseline_total<<','<<1-total/baseline_total<<','<<run.query_ms<<','<<test.query_ms<<','<<violations<<'\n';std::cout<<"degree="<<degree<<" budget="<<budget<<" recall="<<run.recall<<" records="<<run.records<<" route="<<route.total/1024<<" KiB leaf="<<leaf_total/1024<<" KiB total="<<total/1024<<" KiB reduction="<<(1-total/baseline_total)*100<<"% query="<<run.query_ms<<" ms violations="<<violations<<'\n';}
    return 0;
}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}
